SELECT id, 'lost' AS type, NULL AS title, description AS content, images,
       '' AS status, comment_count, like_count, 0 AS view_count, create_time
FROM lost WHERE create_user = #{userId}
ORDER BY create_time DESC
LIMIT #{offset}, #{size}

